#!/usr/bin/env python3
"""Embed the checked public FSR 3.1.5 Vulkan shader bundle as C data.

This is deliberately a tiny standard-library-only generator.  The generated
header is part of the portable backend build, while the input SPIR-V remains
the audited artifact and SHA-256 manifest used by the CTests.
"""

from __future__ import annotations

import argparse
import hashlib
import struct
from pathlib import Path


MODULES = (
    "fsr3_3_1_5_prepare_inputs.spv",
    "fsr3_3_1_5_luma_pyramid.spv",
    "fsr3_3_1_5_shading_change_pyramid.spv",
    "fsr3_3_1_5_shading_change.spv",
    "fsr3_3_1_5_prepare_reactivity.spv",
    "fsr3_3_1_5_luma_instability.spv",
    "fsr3_3_1_5_accumulate.spv",
    "fsr3_3_1_5_accumulate_sharpen.spv",
    "fsr3_3_1_5_rcas.spv",
    "fsr3_3_1_5_debug_view.spv",
    "fsr3_3_1_5_autogen_reactive.spv",
)


def identifier(filename: str) -> str:
    return filename.removesuffix(".spv").upper()


def render_words(data: bytes) -> str:
    words = struct.unpack(f"<{len(data) // 4}I", data)
    rows = []
    for start in range(0, len(words), 8):
        rows.append("    " + ", ".join(f"UINT32_C(0x{word:08x})" for word in words[start:start + 8]) + ",")
    return "\n".join(rows)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("input_directory", type=Path)
    parser.add_argument("output_header", type=Path)
    args = parser.parse_args()

    payloads: list[tuple[str, bytes]] = []
    for filename in MODULES:
        data = (args.input_directory / filename).read_bytes()
        if len(data) == 0 or len(data) % 4:
            raise SystemExit(f"invalid SPIR-V size: {filename}")
        if struct.unpack_from("<I", data)[0] != 0x07230203:
            raise SystemExit(f"not SPIR-V: {filename}")
        payloads.append((filename, data))

    lines = [
        "/* Auto-generated by package_fsr3_3_1_5_spirv.py; do not edit. */",
        "#ifndef FFX_VK_FSR3_3_1_5_EMBEDDED_SPIRV_H",
        "#define FFX_VK_FSR3_3_1_5_EMBEDDED_SPIRV_H",
        "#include <stdint.h>",
        "#include <stddef.h>",
        "typedef struct FfxVkFsr3_3_1_5EmbeddedSpirv {",
        "    const char* filename;",
        "    const uint32_t* words;",
        "    size_t wordCount;",
        "} FfxVkFsr3_3_1_5EmbeddedSpirv;",
    ]
    for filename, data in payloads:
        lines.extend((
            f"static const uint32_t FFX_VK_FSR3_3_1_5_{identifier(filename)}[] = {{",
            render_words(data),
            "};",
        ))
    lines.append("static const FfxVkFsr3_3_1_5EmbeddedSpirv FFX_VK_FSR3_3_1_5_EMBEDDED_SPIRV[] = {")
    for filename, _ in payloads:
        symbol = f"FFX_VK_FSR3_3_1_5_{identifier(filename)}"
        lines.append(f'    {{"{filename}", {symbol}, sizeof({symbol}) / sizeof({symbol}[0])}},')
    lines.extend((
        "};",
        "#define FFX_VK_FSR3_3_1_5_EMBEDDED_SPIRV_COUNT 11u",
        "#endif",
        "",
    ))
    args.output_header.write_text("\n".join(lines), encoding="utf-8")
    digest_lines = [f"{hashlib.sha256(data).hexdigest()}  {filename}" for filename, data in payloads]
    (args.output_header.parent / "EMBEDDED_SOURCE_SHA256SUMS").write_text(
        "\n".join(digest_lines) + "\n", encoding="ascii")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
